:root {
  --ground: #fbfaf7;
  --raised: #ffffff;
  --ink: #23211d;
  --quiet: #6f6a61;
  --line: #e4e0d7;
  --accent: #3d5a80;
  --wash: rgb(0 0 0 / 0.035);
  --door: color-mix(in oklch, var(--accent) 45%, var(--ground));

  --serif: "Source Serif 4", "Iowan Old Style", Charter, "Palatino Linotype", Georgia, serif;
  --sans: "Source Sans 3", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: "Source Code Pro", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* The serif's size, which the lines and the headings are reckoned from,
     and the sans's, matched to it by x-height and lifted a step. */
  --base: 17px;
  --text: calc(var(--base) * 0.967);
  --ratio: 1.5;
  --leading: calc(var(--base) * 1.45);
  --leading-close: 1.5;
  --leading-tight: 1.2;
  --lead: 1.12em;
  --aside: 0.93em;
  --code: 0.8em;
  /* The headings: the scale stands on the ratio over the body, a card's title,
     and each level above it rises by the rise. The scale is fixed, so a place's
     title is the same size wherever one comes to it. An h5 is a backup for a
     brief that really goes that deep, drawn squeezed beneath the scale, and a
     sixth level as the fifth. */
  --rise: 1.4;
  --least: calc(var(--base) * var(--ratio));
  --h5: calc(var(--least) * 0.85);
  --h6: var(--h5);
  --h4: calc(var(--least) * var(--rise));
  --h3: calc(var(--h4) * var(--rise));
  --h2: calc(var(--h3) * var(--rise));
  --title: calc(var(--h2) * var(--rise));
  --heading: 1.1rem;
  --small: 0.875rem;
  --smaller: 0.75rem;
  --step: 12px;

  --measure: 600px;
  --gap: 1rem;
  --inset: 0.8em 1em;
  --radius: 8px;
  --pill: 99px;
  --hairline: 1px;
  --rule: 3px;
  --thin: 0;

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ground: #171614;
    --raised: #1e1d1a;
    --ink: #e8e4dc;
    --quiet: #9b958a;
    --line: #2f2c28;
    --accent: #9db4d6;
